// PRIMARY: beacon_node/execution_layer/src/engine_api/new_payload_request.rs:verify_payload_block_hash (lines 132-158)
pub fn verify_payload_block_hash(&self) -> Result<(), Error> {
    let payload = self.execution_payload_ref();
    let parent_beacon_block_root = self.parent_beacon_block_root().ok().cloned();

    let _timer = metrics::start_timer(&metrics::EXECUTION_LAYER_VERIFY_BLOCK_HASH);

    // Check that no transactions in the payload are zero length
    if payload.transactions().iter().any(|slice| slice.is_empty()) {
        return Err(Error::ZeroLengthTransaction);
    }

    let (header_hash, rlp_transactions_root) = calculate_execution_block_hash(
        payload,
        parent_beacon_block_root,
        self.execution_requests().ok().copied(),
    );

    if header_hash != self.block_hash() {
        return Err(Error::BlockHashMismatch {
            computed: header_hash,
            payload: payload.block_hash(),
            transactions_root: rlp_transactions_root,
        });
    }

    Ok(())
}

